using System.Globalization;
using CsvHelper;
using CsvHelper.Configuration;
using Microsoft.EntityFrameworkCore;
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.ML.Transforms.TimeSeries;
namespace FinSense;
public record CsvRow(int Line, string Date, string Description, string Type, string Amount, string Category, string Reference);
public record RowResult(int Line, string Status, string Reason, Movement? Movement);
public static class Logic {
 public static string? Validate(Movement x,Account? a,Category? c){if(a is null||!a.Active)return "Cuenta inexistente o inactiva.";if(x.Type is not ("ingreso" or "gasto"))return "Tipo inválido.";if(x.Date==default)return "Fecha inválida.";if(string.IsNullOrWhiteSpace(x.Description)||x.Description.Length>200)return "Descripción inválida (máximo 200 caracteres).";if(x.Amount<=0||x.Amount>1000000000m||decimal.Round(x.Amount,2)!=x.Amount)return "Monto inválido.";if(x.CategoryId!=null&&(c is null||!c.Active||c.Type!=x.Type))return "La categoría no corresponde al tipo.";return null;}
 public static Rule? MatchRule(IEnumerable<Rule> rules,string text,string type)=>rules.Where(r=>r.Active&&r.Type==type&&(r.Match=="exacta"?string.Equals(text,r.Pattern,StringComparison.OrdinalIgnoreCase):text.Contains(r.Pattern,StringComparison.OrdinalIgnoreCase))).OrderBy(r=>r.Priority).ThenBy(r=>r.Id).FirstOrDefault();
 public static string CsvSafe(string s){if(s.Length>0&&"=+-@\t\r".Contains(s[0]))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}
 public static List<CsvRow> Parse(byte[] bytes){if(bytes.Length==0||bytes.Length>5*1024*1024)throw new ArgumentException("Archivo vacío o superior a 5 MB.");var text=new System.Text.UTF8Encoding(false,true).GetString(bytes).TrimStart('\uFEFF');using var sr=new StringReader(text);using var csv=new CsvReader(sr,new CsvConfiguration(CultureInfo.InvariantCulture){Delimiter=",",DetectColumnCountChanges=true,MissingFieldFound=null});if(!csv.Read()||!csv.ReadHeader())throw new ArgumentException("CSV sin encabezado.");var h=csv.HeaderRecord??[];foreach(var n in new[]{"fecha","descripcion","tipo","monto"})if(!h.Contains(n))throw new ArgumentException("Falta la columna "+n);var rows=new List<CsvRow>();while(csv.Read()){if(rows.Count>=10000)throw new ArgumentException("Máximo 10.000 filas.");string get(string n)=>h.Contains(n)?csv.GetField(n)?.Trim()??"":"";rows.Add(new(csv.Context.Parser!.Row,get("fecha"),get("descripcion"),get("tipo"),get("monto"),get("categoria"),get("referencia")));}if(rows.Count==0)throw new ArgumentException("El archivo no contiene filas.");return rows;}
 public static async Task<List<RowResult>> Preview(FinanceDb db,int accountId,byte[] bytes){var rows=Parse(bytes);var a=await db.Accounts.FindAsync(accountId);var cats=await db.Categories.ToListAsync();var rules=await db.Rules.ToListAsync();var existing=await db.Movements.Where(x=>x.AccountId==accountId).ToListAsync();var seen=new HashSet<string>();var results=new List<RowResult>();foreach(var r in rows){try{if(!DateOnly.TryParseExact(r.Date,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out var date))throw new ArgumentException("Fecha debe ser AAAA-MM-DD.");if(!decimal.TryParse(r.Amount,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var amount))throw new ArgumentException("Monto inválido.");var type=r.Type.ToLowerInvariant();var cat=string.IsNullOrWhiteSpace(r.Category)?null:cats.FirstOrDefault(c=>c.Name.Equals(r.Category,StringComparison.OrdinalIgnoreCase)&&c.Type==type);if(r.Category!=""&&cat is null)throw new ArgumentException("Categoría desconocida o incompatible.");var rule=cat is null?MatchRule(rules,r.Description,type):null;cat??=rule is null?null:cats.FirstOrDefault(c=>c.Id==rule.CategoryId);var x=new Movement{AccountId=accountId,Date=date,Description=r.Description,Type=type,Amount=amount,CategoryId=cat?.Id,Reference=string.IsNullOrWhiteSpace(r.Reference)?null:r.Reference,Origin="importado",RuleId=rule?.Id};var error=Validate(x,a,cat);if(error!=null)throw new ArgumentException(error);var key=x.Reference is not null?"r:"+x.Reference.ToLowerInvariant():$"v:{x.Date}:{x.Type}:{x.Amount}:{x.Description.ToLowerInvariant()}";var dup=!seen.Add(key)||existing.Any(y=>x.Reference!=null?y.Reference!=null&&y.Reference.Equals(x.Reference,StringComparison.OrdinalIgnoreCase):y.Date==x.Date&&y.Type==x.Type&&y.Amount==x.Amount&&y.Description.Equals(x.Description,StringComparison.OrdinalIgnoreCase));results.Add(new(r.Line,dup?"duplicado":"válido",dup?"Posible duplicado: se omitirá por seguridad.":"",x));}catch(ArgumentException e){results.Add(new(r.Line,"rechazado",e.Message,null));}}return results;}
}
public class Monthly {public float Value {get;set;}}
public class Prediction { [VectorType(1)] public float[] Forecast {get;set;}=[]; }
public static class ForecastService {
 static float Predict(float[] values){var ml=new MLContext(seed:42);var data=ml.Data.LoadFromEnumerable(values.Select(x=>new Monthly{Value=x}));var pipe=ml.Forecasting.ForecastBySsa("Forecast",nameof(Monthly.Value),windowSize:6,seriesLength:values.Length,trainSize:values.Length,horizon:1);var model=pipe.Fit(data);return model.CreateTimeSeriesEngine<Monthly,Prediction>(ml).Predict().Forecast[0];}
 public static object Run(List<Movement> moves,DateOnly today){var current=new DateOnly(today.Year,today.Month,1);var costs=moves.Where(x=>x.Active&&x.Type=="gasto"&&x.Date<current).ToList();if(costs.Count==0)return new{available=false,message="No hay gastos completos para pronosticar."};var first=new DateOnly(costs.Min(x=>x.Date).Year,costs.Min(x=>x.Date).Month,1);var series=new List<(DateOnly month,float amount)>();for(var d=first;d<current;d=d.AddMonths(1))series.Add((d,(float)costs.Where(x=>x.Date.Year==d.Year&&x.Date.Month==d.Month).Sum(x=>x.Amount)));if(series.Count<24)return new{available=false,message=$"Datos insuficientes: {series.Count} meses completos; se requieren 24."};var vals=series.Select(x=>x.amount).ToArray();var errors=new List<float>();var baseline=new List<float>();for(int i=vals.Length-3;i<vals.Length;i++){var predicted=Predict(vals[..i]);if(!float.IsFinite(predicted))throw new InvalidOperationException("El modelo produjo un resultado inválido.");errors.Add(Math.Abs(Math.Max(0,predicted)-vals[i]));baseline.Add(Math.Abs(vals[i-1]-vals[i]));}var p=Predict(vals);if(!float.IsFinite(p))throw new InvalidOperationException("El modelo produjo un resultado inválido.");return new{available=true,history=series.Select(x=>new{month=x.month.ToString("yyyy-MM"),amount=x.amount}),month=current.ToString("yyyy-MM"),forecast=Math.Max(0,p),mae=errors.Average(),baselineMae=baseline.Average(),method="ML.NET SSA",trainedAt=DateTime.UtcNow,warning="Estimación, no gasto real. Meses sin registros se consideran cero; el mes actual se excluye. Valores negativos se limitan a cero."};}
}
